import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public class ScoreInverterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        Map<String, Integer> scores = new LinkedHashMap<>();
        scores.put("carol", 90);
        scores.put("bob", 85);
        scores.put("alice", 90);
        scores.put("dave", 85);
        scores.put("erin", 70);
        Map<Integer, List<String>> inv = ScoreInverter.invert(scores);
        Object at90 = inv == null ? null : inv.get(90);
        Object at85 = inv == null ? null : inv.get(85);
        Object at70 = inv == null ? null : inv.get(70);
        check("names with score 90, sorted", "[alice, carol]",
                at90 == null ? null : at90.toString());
        check("names with score 85, sorted", "[bob, dave]",
                at85 == null ? null : at85.toString());
        check("names with score 70", "[erin]",
                at70 == null ? null : at70.toString());
        check("no entry for an absent score", null,
                inv == null ? null : inv.get(99));
        check("inverted map has one key per distinct score", 3,
                inv == null ? null : inv.size());

        Map<Integer, List<String>> empty = ScoreInverter.invert(new LinkedHashMap<>());
        check("empty input gives empty map", 0,
                empty == null ? null : empty.size());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

